const QUESTIONS = [
  // ===================================================================
  // Part I: Prices and Markets
  // ===================================================================
  q(1, 1, 'easy', 'Sowell defines economics as the study of…', 'The use of scarce resources which have alternative uses', ['How to make money', 'How governments should run the economy', 'The stock market'],
    'Money is just one way of measuring it. The core of economics is choosing among alternative uses of things that are scarce.'),
  q(1, 1, 'easy', 'Can a decision be “economic” if no money is involved?', 'Yes: any choice about using scarce resources with alternative uses is economic', ['No: economics is the study of money', 'Only if a government is involved', 'Only if someone pays taxes on it'],
    'Time, labor and attention are scarce too. Deciding how to use them is an economic decision, cash or no cash.'),
  q(1, 2, 'medium', 'Would a primitive society with no money, or a commune where nobody charges anyone, have any costs?', 'Yes: costs are the alternatives given up, and those exist everywhere', ['No: costs only exist where there are prices', 'Only the costs of imported goods', 'No, because everything is shared'],
    'A cost is a foregone opportunity. Money just puts a number on it; it doesn’t create it.'),
  q(1, 4, 'hard', 'Why is it a problem when a government sets official “national priorities”?', 'Value is incremental: no one goal is worth more than everything else at every margin', ['Politicians always pick the wrong things', 'Priorities can only be set by voters', 'There’s no problem; it’s just good planning'],
    'Some water is worth more than any diamond, but not every extra gallon. Fixed priorities pour resources into one goal long past the point where it’s worth it.'),
  q(1, 2, 'medium', 'Soviet factories were judged by whether they met numerical production targets. What did that tend to produce?', 'Whatever hit the numbers, whether or not anyone wanted it', ['High-quality goods that consumers loved', 'Exactly what consumers needed', 'Fewer goods, but cheaper ones'],
    'Judge output by weight and you get heavy, useless goods; judge it by count and you get flimsy ones. Without prices, nobody asks what consumers actually want.'),
  q(1, 2, 'hard', 'The Soviet economy used more steel and energy per unit of output than market economies. Why?', 'Without prices and profit-and-loss, managers had no reason to economize on inputs', ['Soviet engineers were less educated', 'The cold climate', 'They only produced luxury goods'],
    'In a market, wasting inputs eats into profits. Under central planning, using more resources cost the manager nothing.'),
  q(1, 2, 'hard', 'The Soviet Union often had shortages and unsold surpluses at the same time. How?', 'Prices set by planners didn’t adjust, so goods piled up in one place while lacking in another', ['Spies sabotaged distribution', 'Consumers refused to buy anything', 'Bad weather every year'],
    'Moving prices are what tell producers to make more of one thing and less of another. Freeze them and the signals stop.'),
  q(1, 2, 'medium', 'How can a rise in the demand for paper raise the price of baseball bats?', 'Both are made from wood, so more demand for paper bids up the price of wood', ['Bat makers use paper for packaging', 'Paper and bats are taxed together', 'It can’t; the two markets are unrelated'],
    'Scarce resources have alternative uses. Paper, furniture and bats all compete for the same wood.'),
  q(1, 2, 'hard', 'More demand for cheese can make catchers’ mitts more expensive. Why?', 'More milk means fewer cows slaughtered as calves, so there’s less cowhide for leather', ['Cheese factories buy up leather', 'Higher cheese prices cause general inflation', 'Mitts are wrapped in cheesecloth'],
    'Dairies keep more cows alive to milk them, so fewer go to slaughter, cowhide gets scarcer and leather goods cost more.'),
  q(1, 3, 'medium', 'What’s the difference between scarcity and a shortage?', 'Scarcity means there’s never enough for all wants; a shortage means people can’t get what they’d buy at the current price', ['They’re the same thing', 'Scarcity is temporary; shortages are permanent', 'Shortages only happen in poor countries'],
    'Scarcity is a fact of life everywhere. A shortage is a price problem, usually a price held below what the market would set.'),
  q(1, 3, 'hard', 'Under rent control, can a housing shortage grow even while the amount of housing per person rises?', 'Yes: the low controlled price makes people demand more space than before', ['No: a shortage needs less housing', 'Only if the population grows', 'Only in wartime'],
    'A growing shortage without growing scarcity: rent control made people take more space, so “not enough housing” got worse as housing grew.'),
  q(1, 3, 'medium', 'Can there be a food surplus in a country where people are hungry?', 'Yes: a price kept above the market level leaves food unsold while people go hungry', ['No: hungry people would eat any surplus', 'Only if the food has spoiled', 'Only in communist countries'],
    'In 1930s America, farm produce was plowed under and milk poured down sewers to hold prices up, while children suffered from malnutrition.'),
  q(1, 3, 'medium', 'A housing shortage vanishes almost overnight, before any new homes could have been built. What probably happened?', 'Rent control ended, so people used less space: roommates, smaller places, fewer half-empty flats', ['Lots of people suddenly moved abroad', 'The government secretly built homes', 'Everyone moved to the suburbs the same week'],
    'When rents rise to market levels, people economize on space, and the existing housing goes further.'),
  q(1, 3, 'medium', 'After rent control ends, what usually happens in the longer run?', 'More housing gets built, now that building it pays again', ['Rents keep rising forever', 'Construction stops for good', 'Landlords sell everything to the state'],
    'Higher rents are the signal that tells builders to build. That’s how the shortage goes away for good.'),
  q(1, 3, 'easy', 'A price ceiling holds a product’s price below the market level. What happens to the quantity demanded?', 'It rises', ['It falls', 'It stays the same', 'It drops to zero'],
    'Cheaper things get bought in larger quantities. That’s the first half of every shortage.'),
  q(1, 3, 'easy', 'Under a price ceiling below the market level, what happens to the quantity supplied?', 'It falls', ['It rises', 'It stays the same', 'It doubles'],
    'Producers make less of what pays less. More wanted plus less offered equals a shortage.'),
  q(1, 3, 'medium', 'What tends to happen to the quality of price-controlled goods?', 'It declines, because sellers can cut quality instead of raising the price', ['It rises', 'It stays the same', 'It becomes illegal to change'],
    'In a shortage, customers take what they can get, so sellers have little reason to keep up quality.'),
  q(1, 3, 'medium', 'Which of these does a price ceiling below the market price NOT tend to cause?', 'A surplus', ['Black markets', 'Hoarding', 'Fewer of the services that usually come with the product'],
    'Price ceilings cause shortages. It’s price floors, set above the market, that cause surpluses.'),
  q(1, 3, 'hard', 'During the 1970s gasoline price controls, what happened to services like checking the oil and washing windshields?', 'They were cut back: with a shortage, stations didn’t need to compete for customers', ['They became free', 'They were made compulsory', 'They improved to make up for the lines'],
    'With more customers than gasoline, stations could cut hours and services and still sell out.'),
  q(1, 3, 'medium', 'After rent control laws are passed, how do builders tend to use bricks, pipes and labor?', 'More goes into luxury housing and offices, which are often exempt from the controls', ['More goes into ordinary housing', 'It all moves into farming', 'Nothing changes'],
    'Resources flow to where they earn the most. Controlled ordinary housing earns less, so it gets less.'),
  q(1, 3, 'medium', 'Under rent control, what happens to the average number of people per apartment?', 'It falls: people keep more space than they need, since it’s cheap', ['It rises, from overcrowding', 'It stays the same', 'It doubles as families move in'],
    'In rent-controlled San Francisco, about half the apartments had only one occupant.'),
  q(1, 3, 'medium', 'Under rent control, how long do tenants tend to stay in the same apartment?', 'Longer: nobody wants to give up a cheap controlled apartment', ['Shorter', 'The same as before', 'Exactly one year, by law'],
    'Tenants stay put even when their needs change, so fewer apartments come free for newcomers.'),
  q(1, 3, 'medium', 'What does rent control do to the quality and average age of housing?', 'Quality falls and buildings get older, as upkeep and new construction pay less', ['Both improve', 'Quality rises and buildings get newer', 'It has no effect on either'],
    'With a waiting line of tenants, landlords don’t need to maintain buildings, and few new ones get built.'),
  q(1, 3, 'medium', 'Why do price controls cause a worse shortage of gasoline than of strawberries?', 'Gasoline can be hoarded, in fuller car tanks; strawberries rot', ['People need more gasoline than strawberries', 'Strawberries are imported', 'Gasoline is heavier'],
    'Controls cause hoarding wherever goods keep. Perishable goods and services, like haircuts, can’t be stockpiled.'),
  q(1, 4, 'easy', 'Are prices usually higher or lower in low-income neighborhoods?', 'Higher, because costs there are higher: crime, insurance, slower turnover, riskier loans', ['Lower, because people can afford less', 'The same as everywhere else', 'Higher, because of greedy shopkeepers'],
    'Prices reflect costs. It costs more to run a store, or lend money, where losses are more likely.'),
  q(1, 4, 'medium', 'Why do check-cashing services charge more than banks charge their customers?', 'Their customers have no bank accounts or credit records, so each check is riskier and costlier to handle', ['They are a monopoly', 'Banks are subsidized by law', 'They only serve the rich'],
    'A bank knows its account holders already. A check casher is taking a chance on a stranger every time.'),
  q(1, 4, 'hard', 'When a government program backfires, does that prove its officials are irrational or incompetent?', 'No: they may be responding rationally to the incentives and constraints they face', ['Yes, always', 'Only if they were elected', 'No, because government programs never backfire'],
    'Officials are judged by different things than businesses are. Rational people in a badly designed system produce bad results.'),

  // ===================================================================
  // Part II: Industry and Commerce
  // ===================================================================
  q(2, 7, 'medium', 'Why would a corporation pay millions to get rid of a CEO who has failed?', 'Keeping a failing CEO can cost billions, so ending it fast is cheaper', ['The board are his friends', 'Federal law requires it', 'To reward failure on principle'],
    'Like a divorce, it can cost more than the wedding, but delays can cost far more than the “golden parachute.”'),
  q(2, 6, 'medium', 'Toyota kept only hours’ worth of parts on hand; Soviet factories kept almost a year’s worth. Why?', 'Toyota’s suppliers delivered reliably; Soviet suppliers didn’t, so factories hoarded', ['Toyota was poorer', 'Soviet factories were bigger', 'Toyota made fewer cars'],
    'Japanese suppliers often delivered three or four times a day. Soviet economists said their inventories nearly equaled a year’s output.'),
  q(2, 6, 'hard', 'Why are huge inventories a handicap, not an advantage?', 'They use up resources without adding anything to anyone’s standard of living', ['They attract thieves', 'They are heavily taxed', 'They aren’t; more is always safer'],
    'Inventory costs money and earns nothing. Soviet economists called it a heavier weight than capitalist recessions.'),
  q(2, 6, 'hard', 'Why did big Chinese firms long transport their own goods instead of hiring transport companies?', 'Government transport firms had no incentive to deliver on time or handle goods carefully', ['Chinese law banned trucking firms', 'It was cheaper', 'To employ more people'],
    'A TV maker might move its sets less efficiently, but it wouldn’t smash them. China ended up spending about twice the US share of income on transport.'),
  q(2, 5, 'medium', 'Why did mail-order houses like Montgomery Ward and Sears thrive in the late 1800s?', 'Most Americans lived in rural areas, and mail order delivered goods cheaper than local stores', ['Stores were banned in rural areas', 'People preferred catalogs to shops', 'The post office paid them to'],
    'With railroad tracks running through their Chicago warehouses, they undersold rural stores, driving many out of business.'),
  q(2, 5, 'hard', 'Robert Wood saw that urban department stores would beat mail order. What happened to him at Montgomery Ward?', 'He was fired, joined Sears, and Sears built stores first', ['He was promoted to CEO', 'He was ignored but kept on', 'He bought the company'],
    'Meanwhile J.C. Penney, who started with little money, built over a thousand stores by 1930. Ward followed late and never caught up.'),
  q(2, 5, 'medium', '“The market exacts a price for inertia.” What happened to Montgomery Ward after it clung to mail order?', 'It lost ground to Sears and never caught up', ['It thrived; customers loved tradition', 'The government bailed it out', 'It bought Sears'],
    'Insight beat size: those who read the changing country right overtook giants who didn’t.'),
  q(2, 5, 'hard', 'When Sewell Avery stepped down as Montgomery Ward’s chief executive, what did its stock do?', 'It rose immediately', ['It fell sharply', 'It didn’t move', 'Trading was suspended'],
    'He’d hoarded so much cash that Fortune called the company “a bank with a store front,” while Sears used its money to expand.'),
  q(2, 6, 'medium', 'General Motors buys its tires; Soviet firms made their own parts, sometimes even their own bricks. Why?', 'Soviet suppliers were unreliable, so firms made everything themselves', ['Soviet firms were more efficient', 'GM is banned from making tires', 'Tires were scarcer in America'],
    'Specializing only pays when you can count on other specialists to deliver.'),
  q(2, 6, 'easy', 'In a market economy, what job do losses do?', 'They force a stop to using resources in ways consumers don’t value', ['None; only profits matter', 'They prove the owners were greedy', 'They’re a sign the government should step in'],
    'Profits pull resources toward what people want; losses push them away from what people don’t. Both are signals.'),
  q(2, 6, 'medium', 'Soviet tractor drivers were paid by the area they plowed. What did they do?', 'Plowed deep around the edges and lifted the plow in the middle, where no one could see', ['Plowed extra carefully', 'Refused to plow', 'Plowed only at night'],
    'Plan fulfillment was counted in hectares worked, so covering ground fast beat plowing well.'),
  q(2, 6, 'hard', 'If those tractor drivers had been plowing their own farms, what would likely change?', 'They’d plow properly, and farms would be smaller: sized so owners could oversee them', ['Nothing would change', 'Farms would get even bigger', 'They’d hire more supervisors'],
    'Huge collective farms had diseconomies of scale: too big to monitor. Owners have every reason to do the work right.'),
  q(2, 7, 'medium', 'What made it possible to pool the savings of millions of people to build railroads?', 'Corporations with limited liability, so investors risk only what they put in', ['Government ownership', 'National lotteries', 'Compulsory savings'],
    'Without limited liability, buying one share could put your house at risk, and few would invest in ventures they can’t watch.'),
  q(2, 6, 'medium', 'Advertising is often said to benefit only the advertiser. Is that right?', 'No: it informs consumers, and bigger sales can cut costs and prices', ['Yes; consumers just pay more', 'Only TV advertising helps consumers', 'It only matters for luxury goods'],
    'Advertising spreads information people would otherwise spend time and money to find, and brands put a reputation on the line.'),
  q(2, 6, 'medium', 'Why do retired people get such cheap rates on cruises?', 'They can travel in the off season, when ships would otherwise sail with empty cabins', ['Out of pity', 'Laws require senior discounts', 'They eat less'],
    'Off-season passengers cost little extra, since the ship sails anyway. Retirees aren’t tied to work vacations or school calendars.'),
  q(2, 6, 'easy', 'Why is the old dream of “eliminating the middleman” always frustrated?', 'Someone still has to do the middleman’s job, and middlemen survive by doing it cheaper', ['Middlemen have political power', 'Laws protect them', 'Customers like chatting with them'],
    'If you could do the middleman’s job cheaper yourself, you already would.'),
  q(2, 6, 'hard', 'The A & P grocery chain cut its profit margins, and its rate of profit on investment rose. How?', 'Lower prices sold goods faster, so the same capital turned over many more times a year', ['It cut wages', 'Accounting tricks', 'A government subsidy'],
    'A small profit on each sale, made many more times a year, can beat a big profit on fewer sales.'),
  q(2, 6, 'medium', 'Why might a luxury hotel charge less than a budget hotel nearby?', 'Budget travelers book cheap hotels early, so when tourism dips, the luxury hotels are left empty', ['Luxury hotels are subsidized', 'The budget hotel is secretly nicer', 'Price-fixing'],
    'In Cancún, a Best Western was $180 a night while the nearby Ritz-Carlton was $169. One was full, the other wasn’t.'),
  q(2, 8, 'medium', 'What’s the difference between protecting competition and protecting competitors?', 'Protecting competitors shields less efficient firms, raising costs for consumers', ['There’s no difference', 'Protecting competitors lowers prices', 'Competition can only be protected by tariffs'],
    'Competition means the efficient win customers. Rules that save the losers waste scarce resources.'),
  q(2, 6, 'hard', 'Stores in low-income areas charge more to cover higher costs. What stops them charging enough to earn normal profits?', 'Higher prices drive customers to shop in other neighborhoods', ['Price controls', 'Unions', 'Nothing; they earn more than other stores'],
    'Prices can only rise so far before shoppers go elsewhere, so these stores tend to earn less, and fewer open.'),
  q(2, 9, 'medium', 'In a market economy, what coordinates millions of producers and consumers who’ve never met?', 'Prices, which carry information about scarcity and what people want', ['A central planning board', 'Industry associations', 'Nothing; it’s pure chaos'],
    'Nobody needs to know why copper got scarcer. The higher price tells everyone to use less of it.'),
  // ===================================================================
  // Part III: Work and Pay
  // ===================================================================
  q(3, 10, 'medium', 'As machines replaced human muscle, what became more valuable at work?', 'Knowledge, skills and experience', ['Physical strength', 'Seniority, by law', 'Union membership'],
    'Industrialization shrank the advantage of brute strength and made experience pay, which also opened more doors to women.'),
  q(3, 10, 'hard', 'Peak earnings now come later in life, and are a bigger multiple of beginners’ pay. What does that mean for women who take years off to raise children?', 'They lose more ground, because years of continuous experience count for more', ['Nothing changes for them', 'They catch up faster than before', 'They end up earning more than men'],
    'When experience is worth more, gaps in experience cost more. Much of the male-female earnings gap tracks that.'),
  q(3, 10, 'hard', 'Would the average factory hammer drive more nails a year in a richer country or a poorer one?', 'A poorer country, where scarce tools get used more intensively', ['A richer country', 'The same everywhere', 'Neither; hammers are obsolete'],
    'Where capital is scarce, each tool is worked harder; where it’s plentiful, tools sit idle more often.'),
  q(3, 10, 'medium', 'Who produces more output per hour: the average worker in a richer country or in a poorer one?', 'In a richer country, with more capital and better equipment per worker', ['In a poorer country, because they work harder', 'The same everywhere', 'It depends only on hours worked'],
    'Output per worker depends heavily on what they work with. That’s also why pay is higher there.'),
  q(3, 10, 'medium', 'Can income per person rise 50 percent while average household income stays flat?', 'Yes, if households are getting smaller', ['No, that’s impossible', 'Only with high inflation', 'Only if taxes fall'],
    'Fewer people per household means each household’s income is shared by fewer people. Household figures can hide rising living standards.'),
  q(3, 10, 'medium', 'Is income inequality greater in a single year, or over people’s whole lives?', 'In a single year: most people move between income brackets as they age', ['Over whole lifetimes', 'Exactly the same either way', 'It depends only on tax rates'],
    'The young beginner and the peak-earning veteran are often the same person at different ages.'),
  q(3, 10, 'medium', 'Why do statistics about “the poor” include many people who aren’t really poor?', 'They include students, beginners and others whose low income is temporary', ['Because of fraud', 'They count wealth, not income', 'They count only immigrants'],
    'A bracket is a snapshot. Many in the bottom bracket this year will be in higher ones later.'),
  q(3, 10, 'hard', '“A growing share of income goes to the top 10 percent.” In what sense is that misleading?', 'The top bracket isn’t the same people over time; people move in and out of it', ['It’s simply false', 'It ignores inflation', 'It counts only salaries'],
    'It’s true of statistical categories, not of flesh-and-blood people, who move between brackets over the years.'),
  q(3, 10, 'medium', 'If unionized city bus drivers are paid above the market rate, what tends to happen to the buses?', 'They get bigger and come less often, so fewer drivers are needed', ['They get smaller and come more often', 'Nothing changes', 'Fares go down'],
    'When drivers cost more, transit systems economize on drivers: bigger buses, longer waits.'),
  q(3, 10, 'medium', 'How can bad roads or corruption lower the value of a country’s labor?', 'They reduce the value of what workers can produce, so employers can’t pay as much', ['They can’t; labor is labor', 'Workers simply work less', 'They raise wages through danger pay'],
    'A worker’s pay reflects the value of the output, and that depends on getting goods to market and keeping what you earn.'),
  q(3, 10, 'medium', 'Why isn’t a worker’s productivity the same thing as their merit?', 'It depends on much more than the worker: equipment, management, the people around them', ['It is the same thing', 'Productivity measures only hours', 'Merit is set by unions'],
    'A great hitter in a weak lineup sees fewer good pitches. A skilled worker with poor tools produces less.'),
  q(3, 11, 'easy', 'What does a minimum wage set above many workers’ productivity tend to do?', 'Price low-skilled workers out of jobs', ['Raise everyone’s income', 'Have no effect at all', 'Create a shortage of workers'],
    'An employer won’t keep paying someone more than their work brings in. The least experienced are hit hardest.'),
  q(3, 11, 'hard', 'Studies surveyed firms before and after a minimum wage rise, then added up their jobs. What’s wrong with that method?', 'Firms that went out of business aren’t in the second survey', ['Firms lie about their staff', 'Too few firms answer', 'Nothing; it’s a sound method'],
    'If some firms close and the survivors hire a few of their workers, a survey of survivors shows jobs “rising.”'),
  q(3, 11, 'hard', 'Under World War II wage controls (a maximum wage), what happened to discrimination against minorities and women?', 'It fell: with a labor shortage, employers couldn’t afford to turn anyone away', ['It rose', 'Nothing changed', 'The law banned it outright'],
    'When workers are scarce, refusing to hire someone costs the employer dearly. Women and black workers got jobs they hadn’t before.'),
  q(3, 11, 'medium', 'How does a minimum wage set above the market rate affect discrimination?', 'It makes discrimination cheaper: with more applicants than jobs, employers can pick and choose at no cost', ['It reduces discrimination', 'It has no effect', 'It eliminates discrimination entirely'],
    'A surplus of applicants means turning some away costs nothing, whatever the reason.'),
  q(3, 11, 'hard', 'Tiger Wheels expanded in Poland rather than South Africa, where unemployment was 26 percent and output per hour was higher. Why?', 'South African minimum wages and labor rules made hiring there unprofitable', ['Poland was closer to its suppliers', 'Polish tax breaks', 'Polish workers were more skilled'],
    'It earned a profit in Poland and would only break even or lose money in South Africa, where would-be workers stayed jobless.'),
  q(3, 12, 'medium', 'What effect have multinational corporations had on wages in China?', 'They paid more than local firms and helped push wages up', ['They pushed wages down', 'No effect at all', 'They cut pay and banned unions'],
    'Foreign firms competing for workers raised wages and working conditions, even if they still looked low to Western eyes.'),
  q(3, 12, 'hard', 'In 2010 the share of American adults with jobs fell the most in half a century, yet the unemployment rate didn’t rise. How?', 'People who stopped looking for work aren’t counted as unemployed', ['The statistics were faked', 'Everyone switched to part-time', 'Immigrants were excluded from the count'],
    'The unemployment rate only counts people looking for work. Discouraged workers leave the labor force and the statistic.'),
  q(3, 12, 'medium', 'Why are wages lower in Third World countries?', 'Lower productivity: less capital, fewer skills, poorer infrastructure', ['Greedy multinationals', 'People there work less', 'There are no unions'],
    'Pay tracks the value of what workers produce. Raise that, and wages follow.'),
  q(3, 12, 'hard', 'What tends to happen if a poor country forces wages and working conditions up by law?', 'Fewer jobs and less investment, so many workers end up worse off', ['Everyone gets richer', 'Nothing changes', 'Productivity rises to match'],
    'Employed insiders may gain, but outsiders lose jobs that would have existed. South Africa is a case in point.'),

  // ===================================================================
  // Part IV: Time and Risk
  // ===================================================================
  q(4, 13, 'medium', 'Does it make sense for a 90-year-old with no heirs to plant trees that take 20 years to bear fruit?', 'Yes: the land becomes more valuable right away, because of the fruit to come', ['No: he won’t live to see it', 'Only for tax reasons', 'Only if the government buys the fruit'],
    'Future benefits have a present value. He could sell the land for more as soon as the trees are planted.'),
  q(4, 13, 'medium', 'Why do “known reserves” of oil understate how much is in the ground?', 'Proving reserves costs money, so companies only prove enough for the years ahead', ['Governments hide the data', 'Oil keeps regenerating', 'Geologists can’t measure oil'],
    'Known reserves have risen for decades despite constant use, because exploring further ahead doesn’t pay until it’s needed.'),
  q(4, 13, 'easy', 'Why do “payday loans” have annual interest rates of over 100 percent?', 'Small, short loans carry fixed costs and high risk, and annualizing a short fee inflates the rate', ['Pure greed', 'They’re unregulated', 'Inflation'],
    'A fee for a two-week loan looks enormous when multiplied out to a full year.'),
  q(4, 13, 'medium', 'How does commodity speculation differ from gambling?', 'Gambling creates risks; speculation takes on risks that already exist', ['There’s no difference', 'Speculation is illegal', 'Gambling is safer'],
    'Farmers face weather and price risks whatever happens. Speculators take those risks off their hands, for a price.'),
  q(4, 13, 'hard', 'What does commodity speculation do for the allocation of scarce resources?', 'It spreads them over time, storing goods when they’re plentiful for when they’re scarce', ['It wastes them', 'Nothing useful', 'It raises prices permanently'],
    'Buying low and selling high means buying when there’s plenty and selling when there’s little.'),
  q(4, 13, 'medium', 'Can poor, poorly educated Third World farmers benefit from complex international commodity markets?', 'Yes: world prices reach them, and buyers who deal in those markets pass on the benefits', ['No, never', 'Only with government help', 'Only the biggest farms can'],
    'Farmers don’t need to understand futures contracts any more than drivers need to understand engines.'),
  q(4, 13, 'medium', 'What kinds of income are called “unearned”?', 'Interest, dividends and rent', ['Wages', 'Salaries', 'Tips'],
    'They’re payments for waiting and for taking risks. Someone gave up using the money or property now.'),
  q(4, 13, 'medium', 'What does the interest rate allocate?', 'Resources between present and future uses', ['Nothing; it’s just bank profit', 'Wages between workers', 'Land between farmers'],
    'Interest is the price of time: it rations resources between people who want them now and uses that pay off later.'),
  q(4, 13, 'hard', 'In 2001 Standard & Poor’s downgraded California’s bonds, though the state paid on time and had billions in surplus. Why?', 'Its electricity-crisis commitments meant heavy taxes or debt were coming', ['A political vendetta', 'A clerical error', 'Its surplus was illegal'],
    'Bond analysts look past election day. A year later the state’s finances caught up with what they’d seen.'),
  q(4, 14, 'hard', 'When do individuals raise money with the equivalent of stocks rather than loans?', 'When the outcome is very risky: say, a manager takes a share of a young boxer’s future earnings', ['When buying a house', 'When paying taxes', 'When interest rates are low'],
    'Most young boxers or actors never make it, so loans would never be repaid. A share of the few winners covers the losers.'),
  q(4, 14, 'medium', 'Why do both an insurer and the insured come out ahead?', 'The insurer spreads many risks; the insured swaps an uncertain loss for a small, certain cost', ['They can’t; one side must lose', 'Government subsidies', 'Insurers never actually pay'],
    'Risk shrinks when it’s pooled. That reduction is what both sides share.'),
  q(4, 14, 'medium', 'It makes sense for you to insure your car. Why doesn’t Hertz insure its cars?', 'With so many cars its losses are predictable, so it can cover them itself without paying for an insurer’s costs', ['It’s illegal for rental firms', 'Rental cars never crash', 'Customers pay for all damage'],
    'A big fleet is already a pool of risks. Insurance would only add the insurer’s costs and profit.'),
  q(4, 14, 'hard', 'How can government regulation make the insurance industry less efficient?', 'By forcing insurers to charge the same rates for different risks, or capping prices', ['By requiring reserves to pay claims', 'It can’t', 'By licensing agents'],
    'Charge low-risk and high-risk drivers the same and low-risk drivers subsidize the rest, or insurers just leave.'),
  q(4, 14, 'medium', 'How can government regulation make the insurance industry more efficient?', 'By requiring enough reserves that insurers can actually pay claims', ['By capping premiums', 'By banning risk-based rates', 'By setting one price for everyone'],
    'Rules that make insurers honest and solvent help. Rules that fight the facts of risk hurt.'),
  q(4, 15, 'hard', 'Why might a government-run bus company set fares too low to replace its buses as they wear out?', 'Low fares win approval now; the cost arrives later, when the buses are worn out', ['It has no costs', 'Buses last forever', 'To make a big profit'],
    'Politics looks to the next election. The bill for running down the fleet comes due after it.'),
  q(4, 15, 'hard', 'If a private bus company’s managers paid themselves more instead of saving for new buses, what would happen?', 'Its stock would fall as the fleet decayed, and shareholders would sell or replace management', ['Nothing', 'Its stock would rise', 'The government would step in'],
    'The stock price reflects the company’s future, so running down capital shows up now, not years later.'),
  q(4, 15, 'medium', 'Why has seizing foreign-owned businesses or land seldom made poor countries richer?', 'Much of the value was skills and know-how that left with the owners, and investors stayed away afterwards', ['It always worked', 'The assets were taxed away', 'Foreigners sabotaged them'],
    'Physical assets don’t run themselves, and confiscation tells future investors to keep out.'),

  // ===================================================================
  // Part V: The National Economy
  // ===================================================================
  q(5, 16, 'medium', 'Why does the consumer price index tend to exaggerate inflation?', 'It misses quality improvements, new products and shoppers switching to cheaper goods', ['The government inflates it', 'It only counts luxury goods', 'It’s measured too often'],
    'A computer that costs the same but does far more is really cheaper. The index can’t see that.'),
  q(5, 16, 'medium', 'Why is it hard to say how much national output grew between 1900 and 2000?', 'Much of today’s output didn’t exist then, and the quality of what did has changed', ['The records were burned', 'The currency changed', 'Nobody counted farm output'],
    'How do you compare a world without cars, antibiotics or computers to one with them?'),
  q(5, 16, 'hard', 'During an all-out war, how can military plus civilian consumption exceed a country’s output, without foreign loans?', 'By using up capital: not maintaining or replacing equipment, buildings and inventories', ['By printing money', 'It can’t', 'By working overtime'],
    'The bill comes later, in worn-out factories, roads and machinery.'),
  q(5, 16, 'medium', 'Why is it hard to compare living standards between a young country and an older one?', 'Income rises with age and experience, so a younger population earns less on average', ['Young people spend more', 'Older people aren’t counted', 'Their currencies differ'],
    'Part of what looks like a gap between nations is a gap between age groups.'),
  q(5, 16, 'easy', 'What is “the fallacy of composition”?', 'Assuming that what’s true of a part must be true of the whole', ['Assuming the whole explains every part', 'Confusing correlation with causation', 'Trusting an argument because of who made it'],
    'One person standing up at a game sees better. Everyone standing up doesn’t.'),
  q(5, 16, 'medium', 'Which is an example of the fallacy of composition?', 'A tariff helps one industry, so tariffs must help the whole economy', ['Prices rise when supply falls', 'Rent control causes shortages', 'Interest is the price of time'],
    'Protection helps one industry at the expense of its customers and other industries.'),
  q(5, 17, 'medium', 'During inflation, does money circulate faster or slower?', 'Faster: people spend it before it loses value', ['Slower', 'The same', 'It stops circulating'],
    'Faster spending pushes prices up even further.'),
  q(5, 17, 'hard', 'What happens to the circulation of money during deflation?', 'It slows, as people hold on to money that’s gaining value, deepening the slump', ['It speeds up', 'Nothing changes', 'Deflation makes trade boom'],
    'Holding cash becomes a good investment, so spending, and with it output and jobs, falls further.'),
  q(5, 17, 'medium', 'Hoover and then Roosevelt both tried to keep up prices and wages in the Great Depression. What was the problem?', 'Prices kept above what buyers could pay leave goods unsold and workers unemployed', ['Prices were too low', 'There was no problem', 'It caused hyperinflation'],
    'The aim was to protect purchasing power, but keeping prices up when money is scarce means fewer sales and fewer jobs.'),
  q(5, 17, 'medium', 'Why would an Albanian bank holding 83 percent of the country’s deposits make no loans at all?', 'Weak laws meant it couldn’t collect from defaulters or sell their collateral', ['It had no money', 'Interest was banned', 'Nobody wanted to borrow'],
    'It bought government securities instead, so capital-hungry businesses were left without finance.'),
  q(5, 18, 'medium', 'How do economic policies affect corruption?', 'The more permits and approvals needed, the more chances for bribery', ['They have no effect', 'More regulation always reduces it', 'Only tax rates matter'],
    'Every official who can say no is an official who can be paid to say yes.'),
  q(5, 18, 'medium', 'Do zoning, open-space laws and height limits affect tenants who own no property?', 'Yes: by restricting building, they push up rents', ['No, only owners are affected', 'They lower rents', 'Only commercial tenants'],
    'Property rights matter to everyone who pays for housing, not just to those who own it.'),
  q(5, 18, 'hard', 'Why might affluent people want housing decisions made by politicians or courts, not the market?', 'They can stop building near them without buying the land, while others bear the cost', ['Money doesn’t talk in markets', 'They can’t afford market prices', 'Pure altruism'],
    'Open-space laws keep the views and the property values; newcomers pay in higher rents and prices.'),
  q(5, 18, 'medium', 'Who helped build Britain’s economy before it led the industrial revolution?', 'Skilled foreigners: Lombard bankers, Flemish weavers, Huguenot craftsmen, Jewish financiers and others', ['Its colonies alone', 'The royal family', 'No one; it was all homegrown'],
    'Medieval Britain lagged behind the continent. Immigrants brought skills Britain didn’t have, and Britain let them work.'),
  q(5, 19, 'medium', 'Why do tax rate increases often bring in less revenue than expected?', 'People change behavior: they earn, invest or report less of what’s being taxed', ['Tax collectors get lazy', 'Inflation', 'Taxes are voluntary'],
    'Tax rates and tax revenues are different things.'),
  q(5, 19, 'hard', 'Why can cuts in tax rates sometimes raise government revenue?', 'Money moves out of tax shelters into taxable, productive uses', ['The government prints the difference', 'It never happens', 'Deficits count as revenue'],
    'A lower rate on more taxable income can bring in more than a high rate on income hidden in shelters.'),
  q(5, 19, 'hard', 'When is the burden of the national debt passed on to future generations?', 'When the borrowing pays for current consumption rather than lasting investments', ['Always', 'Never', 'Only when foreigners hold the bonds'],
    'Borrowing to build a dam is like a mortgage on a house; borrowing for this year’s spending is living beyond your means.'),
  q(5, 19, 'medium', 'Why is it hard to tell who really pays a tax?', 'Taxes get passed on: a tax on business can fall on customers, workers or stockholders', ['The records are secret', 'Nobody really pays taxes', 'Only the rich pay'],
    'Who writes the check isn’t necessarily who bears the cost.'),

  // ===================================================================
  // Part VI: The International Economy
  // ===================================================================
  q(6, 21, 'medium', 'How can import restrictions meant to save jobs end up costing jobs?', 'Industries that use the protected product pay more and cut jobs', ['They can’t', 'Workers retire early', 'Exports rise too much'],
    'Steel tariffs cost steel-using industries about 26,000 jobs and $600 million in profits.'),
  q(6, 21, 'hard', 'US restrictions on sugar imports saved jobs in sugar. How many jobs did they cost in candy-making, for each one saved?', 'About three', ['None', 'About half a job', 'About ten'],
    'Some candy makers moved to Canada, Mexico or Guatemala, where sugar was cheaper.'),
  q(6, 21, 'easy', 'Country A can make something more cheaply than country B. Why might A still buy it from B?', 'Comparative advantage: A’s resources earn more making something else', ['Out of charity', 'Because of a treaty', 'Because of tariffs'],
    'What matters is what else those resources could have made: the opportunity cost.'),
  q(6, 21, 'medium', 'Why didn’t prosperous Australia design and build its own cars?', 'Its small market can’t reach the economies of scale needed to cover the design costs', ['It had no engineers', 'It was banned by treaty', 'The climate is too hot'],
    'Designing a car costs a fortune. Spreading it over a few hundred thousand buyers makes each car far dearer.'),
  q(6, 21, 'medium', 'Why is free trade worth more to producers in a small economy than in a big one?', 'Their home market is too small for economies of scale', ['Small countries have better workers', 'Big countries ban imports', 'It isn’t'],
    'Access to world markets lets small-country firms produce at the scale that keeps costs down.'),
  q(6, 21, 'medium', 'What is a “favorable balance of trade,” and why was it called favorable?', 'Exporting more than you import; mercantilists believed it brought in gold, and gold was wealth', ['Importing more than you export, because you get more goods', 'Trade with friendly countries', 'Balanced trade, because it’s fair'],
    'The name stuck long after the theory behind it was discredited.'),
  q(6, 21, 'hard', 'Is a “favorable” balance of trade actually good for prosperity?', 'Not necessarily: wealth is goods and services, and countries have prospered with trade deficits', ['Yes, always', 'Yes, but only for small countries', 'No, it always causes recessions'],
    'The United States has had trade deficits through long periods of prosperity.'),
  q(6, 21, 'medium', 'Which reason for restricting trade do economists usually accept as valid?', 'National defense: keeping militarily vital industries at home', ['Saving jobs in a particular industry', 'Ending a trade deficit', 'Low wages abroad'],
    'Most other arguments for protection don’t survive scrutiny.'),
  q(6, 21, 'medium', 'With free trade, would low-wage countries take away the jobs of high-wage countries?', 'No: what matters is labor cost per unit of output, and higher-paid workers are usually more productive', ['Yes, all of them', 'Only factory jobs', 'Only if currencies float'],
    'If low wages alone decided things, the poorest countries would be the industrial giants.'),
  q(6, 21, 'medium', 'EU trade restrictions save about 200,000 jobs, at a cost of $43 billion a year. Could it pay each displaced worker $100,000 a year and come out ahead?', 'Yes: each job saved costs about $215,000 a year', ['No, it would lose money', 'It would break even', 'There’s no way to tell'],
    'And the displaced workers could simply find other jobs.'),
  q(6, 21, 'hard', 'What’s a problem with laws against “dumping” (selling abroad below cost)?', 'Costs are hard to pin down, and selling below cost is normal at times, so the laws end up protecting domestic firms', ['Dumping never happens', 'They make imports too cheap', 'There’s no problem'],
    'Sales, new products and surplus stock are all sold below average cost, by domestic firms too.'),
  q(6, 22, 'hard', 'The US is often a “debtor nation” and Switzerland a “creditor nation.” Is being a debtor nation harmful?', 'Not necessarily: it often reflects foreigners investing in a growing economy', ['Yes, it means bankruptcy', 'It means a trade surplus', 'It means poverty'],
    'Foreigners buying American assets counts as debt, but it reflects confidence in the economy.'),
  q(6, 22, 'medium', 'Why does capital seldom flow to the countries where it’s scarcest?', 'Insecure property rights, corruption and instability make investing there risky', ['Laws everywhere forbid it', 'They’re too far away', 'Capital prefers cold climates'],
    'Capital doesn’t flow downhill like water. It flows to where it can earn a return and stay safe.'),
  q(6, 23, 'medium', 'Africa is more than twice Europe’s size, but Europe has the longer coastline. Why does that matter?', 'Europe’s indented coast has many natural harbors, which helped trade', ['It doesn’t matter', 'More beaches for tourism', 'More fish'],
    'Much of Africa’s coastline is smooth, with few good harbors, and many of its rivers aren’t navigable to the sea.'),
  q(6, 23, 'medium', 'What effect do mountains tend to have on the people who live in them?', 'Isolation and poverty: costly transport and less contact with other cultures', ['Wealth from minerals', 'Better health, nothing else', 'No effect'],
    'Mountain peoples around the world have often lagged behind the lowlands below them.'),
  q(6, 23, 'hard', 'What do mountains do for the lowlands below them?', 'They supply water and fertile soil washed down from the slopes', ['Nothing', 'They block all trade', 'They make the lowlands poorer'],
    'The same mountains that isolate their own people can enrich the valleys and plains below.'),
  q(6, 23, 'medium', 'When Europeans first met the indigenous peoples of the Americas, what gave Europeans a decisive edge?', 'A far larger cultural universe, drawing on knowledge from across Eurasia', ['Greater intelligence', 'Better weather', 'More gold'],
    'Europe borrowed paper, printing, numerals and more from distant peoples. Isolated societies couldn’t draw on such a pool.'),
  q(6, 23, 'hard', 'How did the two sides’ “disease universes” differ?', 'Europeans had built resistance to Eurasian diseases that the indigenous peoples had never met', ['Indigenous peoples carried deadlier diseases', 'There was no difference', 'Europeans had vaccines'],
    'Diseases killed far more of the indigenous population than warfare did.'),
  q(6, 23, 'medium', 'Which of these tends to make a people culturally isolated?', 'Mountains, deserts and a lack of navigable rivers or harbors', ['Many trading ports', 'A widely spoken language', 'Flat, open plains with rivers'],
    'Isolation cuts people off from other peoples’ knowledge, which economic progress depends on.'),

  // ===================================================================
  // Part VII: Special Economic Issues
  // ===================================================================
  q(7, 24, 'medium', 'Why can physically identical things sell for different prices?', 'The costs differ: time, place, convenience, quantity and service', ['Price gouging', 'It’s random', 'Different taxes'],
    'A drink on a plane and the same drink in a supermarket aren’t the same product, economically.'),
  q(7, 24, 'medium', 'If brands were banned, so you knew what a product was but not who made it, what would happen?', 'Quality would fall, since makers couldn’t be held responsible', ['Prices would drop and quality stay the same', 'Nothing', 'Quality would rise'],
    'Brands are accountability. Even when brands are similar, each maker has a reputation to lose.'),
  q(7, 24, 'medium', 'How does the profit motive help an organization achieve its purpose?', 'It forces it to cut waste: an organization that doesn’t serve people efficiently loses money', ['It doesn’t; profit distracts from the purpose', 'Profits buy better publicity', 'Only through tax breaks'],
    'Non-profits can pursue the goals of whoever runs them, at no cost to themselves if they stray.'),
  q(7, 24, 'medium', 'Before laws against racial discrimination, where were black chemists more likely to be hired?', 'At profit-seeking businesses, where discrimination cost money', ['At non-profit universities', 'In government labs', 'Nowhere at all'],
    'Hundreds worked for chemical companies years before non-profit colleges hired black chemistry teachers.'),
  q(7, 24, 'hard', 'How could you test the claim that profits exceed the value of the services businesses provide?', 'See whether non-profit or government providers deliver the same things more cheaply; they seldom do', ['Ask the customers', 'Count the profits', 'It can’t be tested'],
    'If profits were pure waste, profit-free economies should have had lower prices and higher living standards.'),
  q(7, 24, 'medium', 'Can government-set prices for medical care reduce its costs?', 'They can lower the prices, not the costs: you pay in shortages, waiting and quality', ['Yes, always', 'No, they raise prices', 'Only for insured patients'],
    'Price and cost aren’t the same thing.'),
  q(7, 25, 'medium', '“If it saves just one life, it’s worth it.” What’s wrong with that?', 'The cost also costs lives: resources taken from other uses, and poorer societies are less healthy', ['Lives aren’t worth much', 'Safety devices don’t work', 'Nothing'],
    'Spending heavily to save one life in one way can cost more lives in ways nobody sees.'),
  q(7, 25, 'medium', 'Where do natural disasters do the most financial damage, and where do they take the most lives?', 'Most money in rich countries; most lives in poor ones', ['Most money and most lives in poor countries', 'Most lives in rich countries', 'Both evenly spread'],
    'Wealth means more property to damage, but also better buildings and help that save lives.'),
  q(7, 25, 'medium', 'An official in India didn’t want multinationals “getting rich selling face creams to poor Indians.” What does that imply?', 'That officials know better than poor people what they should buy', ['That face creams are dangerous', 'That multinationals don’t pay taxes', 'That India makes better creams'],
    'Poor people choosing to buy something is their decision, made with their own money.'),
  q(7, 26, 'medium', 'How did the mercantilists differ from classical economists like Adam Smith?', 'Mercantilists saw gold as wealth and wanted export surpluses; Smith saw wealth as goods and favored free trade', ['Smith wanted export surpluses', 'There was no real difference', 'Mercantilists invented free trade'],
    'Smith’s Wealth of Nations was largely an attack on mercantilism.'),
  q(7, 26, 'medium', 'What’s wrong with the theory that prices reflect the amount of labor that goes into things?', 'Prices depend on what buyers value: lots of labor can go into something nobody wants', ['Nothing; it’s correct', 'Labor is always free', 'Prices reflect only taxes'],
    'The theory held for about a century before marginal analysis replaced it.'),
  q(7, 26, 'hard', 'Is economics just the ideological opinions of economists?', 'No: economists of very different ideologies have accepted the same analytical findings', ['Yes, entirely', 'Only macroeconomics is', 'Only since computers'],
    'The history of economics shows analysis winning out over the politics of the people doing it.'),
  q(7, 26, 'hard', 'Why is “pass a law to fix this one problem” often a mistake?', 'Everything is interconnected: a fix in one market ripples into others', ['Laws take too long', 'Problems fix themselves', 'Only courts can fix problems'],
    'General equilibrium theory: you can’t change one price without changing others.'),
  q(7, 27, 'medium', 'In wartime, why not control the price of bread but leave caviar uncontrolled?', 'Producers would shift resources out of bread into uncontrolled luxuries, leaving less bread', ['Caviar would get cheaper', 'Bread would get better', 'No reason not to'],
    'Controlling the price of necessities but not luxuries steers resources toward luxuries.'),

  // ===================================================================
  // The basics, from across the book
  // ===================================================================
  q(1, 1, 'easy', 'What is “opportunity cost”?', 'The value of the best alternative you give up', ['The price tag on an item', 'The cost of starting a business', 'A discount coupon'],
    'Whatever you choose, the real cost is what you could have had instead.'),
  q(1, 2, 'easy', 'Why does a diamond cost more than water, even though water is essential for life?', 'Scarcity: water is plentiful, diamonds are rare', ['Diamonds are shinier', 'Corporate greed', 'Water is heavy'],
    'Prices reflect how scarce the next unit is, not how useful the whole supply is.'),
  q(1, 2, 'easy', 'If its price is free to move, what happens to the price of something that becomes scarcer?', 'It rises', ['It falls', 'It stays the same', 'It’s set by the government'],
    'The higher price tells everyone to use less of it and producers to supply more.'),
  q(1, 3, 'easy', 'A law caps rents below the market level. What’s the most likely result?', 'A housing shortage', ['A housing surplus', 'Cheaper and better housing', 'A building boom'],
    'More people want apartments at the low rent, and fewer get built or offered.'),
  q(1, 3, 'easy', 'What is a “black market”?', 'Illegal trading, often at prices above a legal maximum', ['A stock market crash', 'The trade in coal', 'A market for luxury goods only'],
    'When the legal price is below what people will pay, trading moves underground.'),
  q(1, 3, 'easy', 'Farm price supports keep crop prices above the market level. What do they create?', 'Surpluses', ['Shortages', 'Cheaper food', 'Nothing in particular'],
    'At the higher price, farmers grow more and consumers buy less: the difference is a surplus.'),
  q(2, 5, 'easy', 'What happens to most new businesses?', 'They fail within a few years', ['They become big corporations', 'They become monopolies', 'They’re taken over by the government'],
    'Business is a process of trial and error. The ones we hear about are the survivors.'),
  q(2, 6, 'easy', 'How do businesses earn profits in a free market?', 'By serving customers better or more cheaply than the alternatives', ['By exploiting workers', 'Through government favors', 'By luck alone'],
    'Customers who can go elsewhere only pay if they get something worth it.'),
  q(3, 10, 'easy', 'What mainly decides how much an employer will pay a worker?', 'The value of what that worker produces', ['How much the worker needs', 'Government decree', 'The boss’s mood'],
    'An employer who pays more than a worker brings in loses money; one who pays much less loses the worker to a rival.'),
  q(3, 11, 'easy', 'Who tends to be hit hardest by minimum wage laws?', 'Young, inexperienced and low-skilled workers', ['Executives', 'Skilled tradesmen', 'Retirees'],
    'Their work is worth the least to employers so far, so they’re the first priced out of jobs, and out of the experience that would raise their pay.'),
  q(4, 14, 'easy', 'Why do stocks usually earn a higher average return than bonds?', 'Stocks are riskier, so investors need more to hold them', ['Stocks are regulated more', 'Bonds are taxed more', 'Pure tradition'],
    'Bondholders are paid first, a fixed amount. Stockholders get what’s left, if anything.'),
  q(4, 14, 'easy', 'What does an insurance company actually sell?', 'Protection against risk, by pooling many people’s risks', ['Investments', 'Loans', 'Guaranteed profits'],
    'Few houses burn down in a given year, so many small premiums cover the few big losses.'),
  q(5, 16, 'easy', 'What does Gross Domestic Product (GDP) measure?', 'The total output of goods and services produced in a country', ['Government spending', 'The amount of money in circulation', 'The average wage'],
    'It’s a measure of output, not of money or of what the government spends.'),
  q(5, 17, 'easy', 'What is inflation?', 'A general rise in prices, as money loses value', ['A rise in the price of one product', 'Growth in national output', 'A fall in interest rates'],
    'One price rising is a change in relative prices. All prices rising is inflation.'),
  q(5, 17, 'easy', 'If the government prints a trillion dollars and hands it to everyone, what happens?', 'Inflation: more money chasing the same goods pushes prices up', ['Everyone gets rich', 'The economy doubles in size', 'Nothing changes'],
    'Printing money doesn’t print goods. The same output just costs more.'),
  q(6, 21, 'easy', 'Free trade between two countries generally…', 'Benefits both sides', ['Makes both poorer', 'Only helps the richer one', 'Causes war'],
    'Each side trades because it gets something it values more than what it gives up.'),
  q(6, 21, 'easy', 'What does a tariff do to the price of imported goods?', 'Raises it', ['Lowers it', 'Leaves it unchanged', 'Bans them entirely'],
    'A tariff is a tax on imports, and domestic buyers end up paying it.'),
  q(6, 21, 'easy', 'Who pays most of the cost of a tariff?', 'Domestic consumers, through higher prices', ['The foreign government', 'Foreign workers', 'Nobody'],
    'The protected industry gains; everyone who buys its products, or products made from them, pays.'),
  q(7, 26, 'easy', 'Who wrote The Wealth of Nations, published in 1776?', 'Adam Smith', ['Karl Marx', 'John Maynard Keynes', 'Milton Friedman'],
    'Smith launched classical economics with it, attacking the mercantilists.'),
  q(7, 26, 'easy', 'What did Adam Smith’s The Wealth of Nations argue for?', 'Free markets and free trade', ['Central planning', 'Hoarding gold through export surpluses', 'Absolute monarchy'],
    'Smith argued that the wealth of a nation is its goods and services, not its gold.'),
] as const;

export const BASIC_ECONOMICS: Book = {
  id: 'be',
  title: 'Basic Economics',
  author: 'Thomas Sowell',
  parts: PARTS,
  questions: QUESTIONS,
};
